enum AnchorId {
    A_BEGTEXT = 0,     // the code's first bytes (int 3; jmp $-1; 13 nops, never run): the holds' idle is written there
    A_GAME_ENTRY = 1,     // Do_Game (): a wave flown, its loop to its end; srand (1024 * game_wave [cur_game]) at its start
    A_GAME_INIT = 2,     // Do_Game: playerx, playery to their start (144, 160)
    A_BUFFERS = 3,     // Do_Game: displaybuffer cleared, local_cnt = FRAME_COUNT, start_score = plr.score
    A_FRAME_TOP = 4,     // Do_Game's loop: its top (SHADOW_Clear, then IPT_MovePlayer)
    A_THINK = 5,     // Do_Game's loop: startendwave counted down (end_wave at 0), gl_cnt++, the Think () calls
    A_DRAW_PLAYER = 6,     // Do_Game's loop: draw_player, the ship's shadow from curship [playerpic + g_flash]
    A_DRAW_FLAMES = 7,     // Do_Game's loop: the ship's engine flames at player_cx, player_cy
    A_DRAW_POINT = 8,     // Do_Game's loop: ANIMS_DisplayHigh () called, the ship drawn by then: the others' ships drawn here
    A_WAIT = 9,     // Do_Game's loop: the frame's wait (FRAME_COUNT - local_cnt < 3: 140 Hz / 3) done
    A_GAME_END = 10,     // Do_Game's loop left: the wave over (its end, an abort, a death)
    A_ENEMY_SPAWN = 11,     // ENEMY_Think: the wave's next sprites at the scroll's row: ENEMY_Add (cur_enemy) called
    A_ENEMY_LIST = 12,     // ENEMY_Think: the live enemies (first_enemy.next .. &last_enemy)
    A_KILL = 13,     // ENEMY_Think: an enemy's hits gone (<= 0): plr.score += curlib->money, its explosion, its bonus
    A_ENEMY_CLEAR = 14,     // ENEMY_Clear: free_enemy = ships, the wave's sprites (csprite, ml->numsprites)
    A_DIFF = 15,     // ENEMY_LoadSprites: a sprite's level & cur_diff (the difficulty's sprites)
    A_CURPLR = 16,     // ENEMY_Add: a boss halved at curplr_diff <= DIFF_1
    A_LAUNCH = 17,     // WIN_MainLoop: the ship computer's sector chosen (cur_game, game_wave): the wave's song, its load, Do_Game next
    A_OBJS_AMT = 18,     // OBJS_GetAmt (type): p_objs [type]->num
    A_GLB_FETCH = 19,     // GLB_FetchItem: an item's handle (archive << 16 | item) to its entry (0x28 bytes, +0x10 its memory)
    A_SHOTS_DISPLAY = 20,     // SHOTS_Display: the player's shots (first_shots.next .. &last_shots)
    A_ALT_X = 21,     // Do_Game's loop: KBD_Key (SC_X) && KBD_Key (SC_ALT) (the keys down: a BOOL a scan code)
    A_TILE_KILL = 22,     // TILE_Think: a tile's hits gone (< 0) and not dead: plr.score += money [mapspot] (the map spot in [ebp - 0x14])
    A_COUNT = 23
};
