enum DataId {
    D_CUR_GAME = 0,     // the sector flown (0 Bravo, 1 Tango, 2 Outer Regions)
    D_GAME_WAVE = 1,     // the wave of each sector (4 dwords)
    D_DRAW_PLAYER = 2,     // the ship drawn (0 once it has blown up)
    D_PLAYERX = 3,     // the ship's left (5..314)
    D_PLAYERY = 4,     // its top (0..160)
    D_DISPLAYBUFFER = 5,     // the pointer to the 320 x 200 frame drawn
    D_FRAME_COUNT = 6,     // FRAME_COUNT (140 a second)
    D_PLR_SCORE = 7,     // plr.score: the pilot's money
    D_STARTENDWAVE = 8,     // the wave's end counting down (-1: not ending)
    D_END_WAVE = 9,     // the wave over (the loop ends)
    D_GL_CNT = 10,     // the frames of the game
    D_PLAYERPIC = 11,     // the ship's frame (its bank)
    D_G_FLASH = 12,     // the ship's flash frame (hit)
    D_CURSHIP = 13,     // the ship's frames (GLB items, the wave's set)
    D_PLAYER_CY = 14,     // the ship's centre y
    D_PLAYER_CX = 15,     // the ship's centre x
    D_TILEPOS = 16,     // the map's scroll (its tile, 9 a row)
    D_TILEY = 17,     // the scroll's row less 3: the wave's sprites at it are added
    D_END_WAVEFLAG = 18,     // the wave's last sprite added
    D_CUR_ENEMY = 19,     // the wave's next sprite (CSPRITE, 0x18 bytes)
    D_END_ENEMY = 20,     // the wave's last sprite
    D_FIRST_ENEMY_NEXT = 21,     // first_enemy.next: the live enemies' list (SPRITE_SHIP, 0xBC bytes: +0x18 x, +0x1C y, +0x50 hits)
    D_LAST_ENEMY = 22,     // &last_enemy: the list's end
    D_PLR_SCORE_KILL = 23,     // plr.score (as the kill adds to it)
    D_SHIPS = 24,     // ships [30]: the enemies' slots
    D_ML = 25,     // the wave's map header
    D_CSPRITE = 26,     // the pointer to the wave's sprites (CSPRITE, 0x18 bytes each)
    D_CUR_DIFF = 27,     // the difficulty's sprite levels (EB_ bits)
    D_CURPLR_DIFF = 28,     // the pilot's difficulty in this sector (0 training .. 3 elite)
    D_P_OBJS = 29,     // p_objs [type]: the pilot's objects (OBJ: +8 num; 15 the super shield, 16 the energy)
    D_GLB_ITEMS = 30,     // filedesc [0].item: each archive's entries (0xA0 bytes an archive)
    D_FIRST_SHOTS_NEXT = 31,     // first_shots.next: the player's shots (SHOTS, 0x60 bytes: +8 pic, +0xC x, +0x10 y, +0x14 move, +0x58 lib)
    D_LAST_SHOTS = 32,     // &last_shots: their list's end
    D_KEYBOARD_X = 33,     // keyboard [SC_X]: the keys down (a BOOL a scan code, from keyboard [0] 0xB4 before it)
    D_TILE_HITS = 34,     // the map's tiles' hits (a SHORT a map spot: 9 a row, 150 rows)
    D_TILE_DEAD = 35,     // the map's tiles destroyed (a SHORT a map spot)
    D_COUNT = 36
};
